cypress_script:
describe('Contact Form Tests', () => {
  it('should successfully submit the contact form', () => {
    cy.visit('https://automationexercise.com/contact_us');
    cy.get('input[name="name"]').type('John Doe');
    cy.get('input[name="email"]').type('john.doe@example.com');
    cy.get('input[name="subject"]').type('Feedback');
    cy.get('textarea#message').type('This is a test message.');
    cy.get('input[name="submit"]').click();
    cy.url().should('not.eq', 'https://automationexercise.com/contact_us');
  });

  it('should not submit the contact form when fields are empty', () => {
    cy.visit('https://automationexercise.com/contact_us');
    cy.get('input[name="submit"]').click();
    cy.url().should('eq', 'https://automationexercise.com/contact_us');
    cy.get('input[name="name"]').should('be.visible');
    cy.get('input[name="email"]').should('be.visible');
    cy.get('input[name="subject"]').should('be.visible');
    cy.get('textarea#message').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Contact Form Tests', () => {
  test('should successfully submit the contact form', async ({ page }) => {
    await page.goto('https://automationexercise.com/contact_us');
    await page.fill('input[name="name"]', 'John Doe');
    await page.fill('input[name="email"]', 'john.doe@example.com');
    await page.fill('input[name="subject"]', 'Feedback');
    await page.fill('textarea#message', 'This is a test message.');
    await page.click('input[name="submit"]');
    await expect(page).toHaveURL(/^(?!.*contact_us).*$/);
  });

  test('should not submit the contact form when fields are empty', async ({ page }) => {
    await page.goto('https://automationexercise.com/contact_us');
    await page.click('input[name="submit"]');
    await expect(page).toHaveURL('https://automationexercise.com/contact_us');
    await expect(page.locator('input[name="name"]').isVisible()).toBeTruthy();
    await expect(page.locator('input[name="email"]').isVisible()).toBeTruthy();
    await expect(page.locator('input[name="subject"]').isVisible()).toBeTruthy();
    await expect(page.locator('textarea#message').isVisible()).toBeTruthy();
  });
});
